export function useGetEventList(params: any) {
  return useQuery({
    queryKey: ["eventList"],
    queryFn: async () => {
      if (params.user_id) {
        const additionalParams = {
          goods_code: "GOODS_CODE_A,GOODS_CODE_B",
        };
        const { data } = await api.get(`/api/[endpoint]`, {
          params: {
            user_id: params.user_id,
            status: ["STATUS_CODE"],
            service_code: params.service_code,
            ...(params.service_code === "SERVICE_B"
              && additionalParams),
          },
        });
        return data;
      } else {
        return null;
      }
    },
    enabled: false,
  });
}
